static QByteArray hashFile(const Path& p,std::size_t cap=64*1024*1024){return underlay::digest(underlay::readBounded(p,cap));}
static library::Document importBook(const Path& app,const Path& source,const Path& root){underlay::privateDirectory(root/"inbox");std::filesystem::copy_file(source/"fixtures/library/authored-three-chapters.epub",root/"inbox/authored.epub");std::atomic<bool> stop{false};reader::syncLibrary(app,root,stop);auto books=library::documents(root);CHECK(books.size()==1&&books[0].pages==3&&books[0].format=="epub");return books[0];}
static void settled(ux::Shell& s,Canvas& c){until([&]{s.tick();c.changes();CHECK(!s.failed());return s.writable()&&s.styledInk()&&!s.styledInk()->status().busy&&!s.unsaved()&&!s.semantics().pending();});}
static void navigate(ux::Shell& s,Canvas& c,int page){CHECK(s.navigateTo(page));c.ready();settled(s,c);CHECK(s.page()==page);}
static void apply(ux::Shell& s,Canvas& c,Settings view){CHECK(s.applyEpubView(view));CHECK(s.state()==ux::State::NavigationPending&&!s.writable());c.changes();c.ready();settled(s,c);CHECK(s.state()==ux::State::Clean);}
static QString firstWord(const semantic::Geometry& g){CHECK(g&&g->available());auto words=g->data["words"].toArray(),chars=g->data["chars"].toArray();CHECK(!words.isEmpty());auto indices=words.first().toArray();auto a=chars[indices[0].toInt()].toObject(),b=chars[indices[1].toInt()-1].toObject();return g->data["text"].toString().mid(a["offset"].toInt(),b["offset"].toInt()+b["text"].toString().size()-a["offset"].toInt());}
static QJsonArray strokes(ux::Shell& s,const QString& id){return s.styledInk()->snapshot()["documents"].toObject()[id].toObject()["strokes"].toArray();}
static QJsonObject annotationDocument(ux::Shell& s,const QString& id){return s.styledInk()->snapshot()["documents"].toObject()[id].toObject();}
static void noteSettled(ux::Shell& s,Canvas& c){until([&]{s.tick();c.changes();CHECK(!s.failed());return s.notesPanel()&&s.notesPanel()->view().ready&&s.notesPanel()->canLeave();});}
