static bool coloredHighlight(ux::Shell& s){for(auto pixel:s.visibleInk())if((pixel>>24)&&(pixel&0xffffff)!=0xffffff&&(pixel&0xffffff)!=0)return true;return false;}
static input_event event(unsigned short type,unsigned short code,int value){input_event e{};e.type=type;e.code=code;e.value=value;return e;}
